INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Mandatory content', '[["Nine required items","Issue date, a sequential number, the seller''s VAT number, both parties'' name and address, what was supplied and when, the base, the rate and the VAT."],["Wording for special cases","Reverse charge, exemption and self-billing each need a marker on the face of the invoice, together with the buyer''s VAT number."],["Simplified below DKK 3,000","A short form may drop the buyer''s details, the delivery date and the rate line, with the VAT shown as 20% of the gross."],["Services to consumers","A full invoice is required from DKK 5,000 including VAT, whatever the simplified rules would otherwise allow."]]', 'The Bookkeeping Act''s digital duty binds the system, not the transaction: it governs capability, formats and storage, and changes nothing an invoice must contain. Read from retsinformation''s PDF renditions — its HTML views render only via JavaScript.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Denmark') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Contenido obligatorio', '[["Nueve datos obligatorios","Fecha de emisión, número correlativo, NIF-IVA del vendedor, nombre y dirección de ambas partes, qué se entregó y cuándo, la base, el tipo y el IVA."],["Fórmulas para casos especiales","La inversión del sujeto pasivo, la exención y la autofacturación exigen una marca en la propia factura, junto con el NIF-IVA del comprador."],["Simplificada por debajo de 3.000 DKK","La forma abreviada puede omitir los datos del comprador, la fecha de entrega y la línea del tipo, con el IVA como el 20% del importe bruto."],["Servicios a consumidores","Desde 5.000 DKK con IVA incluido se exige factura completa, aunque las reglas simplificadas permitieran otra cosa."]]', 'El deber digital de la Ley de Contabilidad vincula al sistema, no a la operación: regula capacidad, formatos y conservación, y no altera nada de lo que una factura debe contener. Leído de las versiones PDF de retsinformation; sus vistas HTML solo se generan con JavaScript.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Denmark') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Pflichtangaben', '[["Neun Pflichtangaben","Ausstellungsdatum, fortlaufende Nummer, USt-Nummer des Verkäufers, Name und Anschrift beider Parteien, was wann geliefert wurde, Bemessungsgrundlage, Satz und Steuer."],["Formeln für Sonderfälle","Umkehr der Steuerschuld, Steuerbefreiung und Gutschrift brauchen jeweils einen Vermerk auf der Rechnung, zusammen mit der USt-Nummer des Käufers."],["Vereinfacht unter 3.000 DKK","Die Kurzform darf Kundendaten, Lieferdatum und Steuersatzzeile weglassen; die Steuer wird mit 20% des Bruttobetrags angegeben."],["Leistungen an Verbraucher","Ab 5.000 DKK brutto ist eine vollständige Rechnung erforderlich, unabhängig davon, was die vereinfachten Regeln sonst erlauben würden."]]', 'Die Digitalpflicht des Buchführungsgesetzes bindet das System, nicht den Umsatz: Sie regelt Fähigkeit, Formate und Aufbewahrung und ändert nichts am erforderlichen Rechnungsinhalt. Gelesen aus den PDF-Fassungen von retsinformation; die HTML-Ansichten laufen nur über JavaScript.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Denmark') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Mentions obligatoires', '[["Neuf mentions obligatoires","Date d''émission, numéro séquentiel, numéro de TVA du vendeur, nom et adresse des deux parties, ce qui a été livré et quand, la base, le taux et la TVA."],["Formules pour cas particuliers","L''autoliquidation, l''exonération et l''autofacturation exigent chacune une mention sur la facture, accompagnée du numéro de TVA de l''acheteur."],["Simplifiée sous 3 000 DKK","La forme courte peut omettre les données de l''acheteur, la date de livraison et la ligne de taux, la TVA étant indiquée à 20% du montant brut."],["Services aux consommateurs","À partir de 5 000 DKK TTC, une facture complète est exigée, quoi que permettent par ailleurs les règles simplifiées."]]', 'L''obligation numérique de la loi comptable lie le système, pas l''opération : elle porte sur la capacité, les formats et la conservation, et ne change rien à ce que doit contenir une facture. Lu depuis les versions PDF de retsinformation ; ses vues HTML ne s''affichent qu''en JavaScript.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Denmark') AND d.section = 'file_format' AND d.sort_order = 2;
