SELECT d.id, 'en', 'Identifiers & registration', '[["RUC, eleven digits","Both parties'' RUC appears on a factura. The buyer''s is waived only for a non-resident customer on an export."],["Boleta buyer ID at S/ 700","A boleta needs no RUC, but above S/ 700.00 it must carry the buyer''s name and identity document number."],["SUNAT issues no certificate","Signing uses the taxpayer''s own digital certificate. SUNAT runs no certification authority; it sponsors a free one issued by a state entity."],["No licence to obtain","There is no authorisation to win. In SOL a taxpayer declares itself an issuer by loading a certificate or by naming a PSE or an OSE."]]', 'Vendor pages commonly say an INDECOPI-accredited certificate is required. INDECOPI accredits the certification entities behind Peru''s signature framework, but we found nothing in SUNAT''s own rules making that accreditation a condition of issuing.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Identificadores y registro', '[["RUC, once dígitos","El RUC de ambas partes figura en una factura. El del comprador solo se exceptúa para un cliente no domiciliado en una exportación."],["ID del comprador desde S/ 700","La boleta no exige RUC, pero por encima de S/ 700.00 debe llevar el nombre y el número de documento de identidad del comprador."],["La SUNAT no emite certificados","La firma usa el certificado digital del propio contribuyente. La SUNAT no opera una autoridad de certificación; auspicia uno gratuito emitido por una entidad estatal."],["No hay licencia que obtener","No hay autorización que ganar. En SOL el contribuyente se declara emisor cargando un certificado o designando un PSE o un OSE."]]', 'Las páginas de proveedores suelen afirmar que se exige un certificado acreditado por INDECOPI. INDECOPI acredita a las entidades de certificación del marco peruano de firma, pero no hallamos nada en las normas de la SUNAT que haga de esa acreditación una condición para emitir.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Kennungen und Registrierung', '[["RUC, elf Ziffern","Die RUC beider Parteien steht auf einer Factura. Die des Käufers entfällt nur bei einem gebietsfremden Kunden im Export."],["Käufer-ID ab S/ 700","Eine Boleta braucht keine RUC, muss aber über S/ 700.00 Namen und Ausweisnummer des Käufers tragen."],["SUNAT stellt kein Zertifikat aus","Signiert wird mit dem eigenen digitalen Zertifikat des Steuerpflichtigen. SUNAT betreibt keine Zertifizierungsstelle, fördert aber ein kostenloses von einer staatlichen Stelle."],["Keine Lizenz zu erlangen","Es gibt keine Genehmigung zu gewinnen. In SOL erklärt sich der Steuerpflichtige zum Aussteller, indem er ein Zertifikat hochlädt oder einen PSE oder OSE benennt."]]', 'Anbieterseiten behaupten häufig, ein von INDECOPI akkreditiertes Zertifikat sei erforderlich. INDECOPI akkreditiert die Zertifizierungsstellen des peruanischen Signaturrahmens, doch in den Vorschriften der SUNAT fanden wir nichts, das diese Akkreditierung zur Ausstellungsvoraussetzung macht.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Identifiants et enregistrement', '[["RUC, onze chiffres","Le RUC des deux parties figure sur une factura. Celui de l''acheteur n''est écarté que pour un client non résident à l''export."],["ID de l''acheteur dès S/ 700","Une boleta n''exige pas de RUC, mais au-delà de S/ 700.00 elle doit porter le nom et le numéro de pièce d''identité de l''acheteur."],["La SUNAT n''émet aucun certificat","La signature utilise le certificat numérique du contribuable. La SUNAT n''exploite pas d''autorité de certification ; elle parraine un certificat gratuit délivré par un organisme public."],["Aucune licence à obtenir","Il n''y a pas d''autorisation à décrocher. Dans SOL, le contribuable se déclare émetteur en chargeant un certificat ou en désignant un PSE ou un OSE."]]', 'Les pages d''éditeurs affirment couramment qu''un certificat accrédité par l''INDECOPI est exigé. L''INDECOPI accrédite les entités de certification du cadre péruvien de signature, mais nous n''avons rien trouvé dans les règles de la SUNAT qui en fasse une condition pour émettre.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Peru';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Mandatory content', '[["Core particulars","Series and correlative number, the dates, both parties, a line-by-line description with quantity and unit, the IGV shown apart, and the totals."],["The total in words","The total appears in figures and in words, and the currency is a coded value rather than free text."],["Payment terms since 2021","Every factura states cash or credit, and a credit sale adds the amount outstanding and its due dates."],["The print is not the invoice","Only the XML validated by SUNAT or an OSE has tax force. A printed copy must carry a QR encoding key fields and the XML digest."]]', 'SUNAT''s own PDF of RS 097-2012 is a scanned image with no machine-readable text, so these rows rest on the Reglamento de Comprobantes de Pago and SUNAT''s UBL guides rather than on the electronic-issuance resolution itself.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Contenido obligatorio', '[["Datos principales","Serie y número correlativo, las fechas, ambas partes, el detalle línea a línea con cantidad y unidad, el IGV discriminado y los totales."],["El total en letras","El total figura en cifras y en letras, y la moneda es un valor codificado, no texto libre."],["Condiciones de pago desde 2021","Toda factura indica contado o crédito, y una venta al crédito añade el saldo pendiente y sus fechas de vencimiento."],["El impreso no es la factura","Solo el XML validado por la SUNAT o un OSE tiene efecto tributario. La representación impresa debe llevar un QR con los campos clave y el resumen del XML."]]', 'El PDF de la propia SUNAT de la RS 097-2012 es una imagen escaneada sin texto legible por máquina, por lo que estas filas se apoyan en el Reglamento de Comprobantes de Pago y en las guías UBL de la SUNAT, no en la resolución de emisión electrónica.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Pflichtangaben', '[["Kernangaben","Serie und laufende Nummer, die Daten, beide Parteien, eine zeilenweise Beschreibung mit Menge und Einheit, die gesondert ausgewiesene IGV und die Summen."],["Der Betrag in Worten","Der Gesamtbetrag erscheint in Ziffern und in Worten, und die Währung ist ein codierter Wert, kein Freitext."],["Zahlungsbedingungen seit 2021","Jede Factura nennt Bar- oder Kreditverkauf; beim Kreditverkauf kommen der offene Betrag und seine Fälligkeiten hinzu."],["Der Ausdruck ist nicht die Rechnung","Nur das von SUNAT oder einem OSE validierte XML hat steuerliche Wirkung. Ein Ausdruck muss einen QR mit Schlüsselfeldern und dem XML-Digest tragen."]]', 'Das SUNAT-eigene PDF der RS 097-2012 ist ein Scan ohne maschinenlesbaren Text, daher stützen sich diese Zeilen auf das Reglamento de Comprobantes de Pago und die UBL-Leitfäden der SUNAT statt auf die Resolution zur elektronischen Ausstellung.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Mentions obligatoires', '[["Mentions principales","Série et numéro séquentiel, les dates, les deux parties, un détail ligne par ligne avec quantité et unité, l''IGV isolée et les totaux."],["Le total en toutes lettres","Le total figure en chiffres et en toutes lettres, et la devise est une valeur codée et non du texte libre."],["Conditions de paiement depuis 2021","Toute factura indique comptant ou crédit, et une vente à crédit ajoute le solde dû et ses échéances."],["L''imprimé n''est pas la facture","Seul le XML validé par la SUNAT ou un OSE a force fiscale. Un imprimé doit porter un QR encodant les champs clés et l''empreinte du XML."]]', 'Le PDF de la SUNAT pour la RS 097-2012 est une image numérisée sans texte lisible par machine ; ces lignes s''appuient donc sur le Reglamento de Comprobantes de Pago et les guides UBL de la SUNAT, non sur la résolution d''émission électronique.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Peru';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Archiving', '[["Retention period","5 years minimum, from the first day of the following year"],["What to keep","XML, CDR, rejection notices, daily summaries"]]', 'The exact retention obligation varies slightly by taxpayer regime — confirm your specific rule rather than assuming a flat 5-year figure applies uniformly.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Conservación', '[["Período de conservación","5 años como mínimo, desde el primer día del año siguiente"],["Qué conservar","XML, CDR, avisos de rechazo, resúmenes diarios"]]', 'La obligación exacta de conservación varía ligeramente según el régimen del contribuyente — confirme su regla específica en lugar de asumir que se aplica uniformemente una cifra fija de 5 años.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Aufbewahrung', '[["Aufbewahrungsfrist","Mindestens 5 Jahre, ab dem ersten Tag des Folgejahres"],["Was aufzubewahren ist","XML, CDR, Ablehnungsbenachrichtigungen, Tageszusammenfassungen"]]', 'Die genaue Aufbewahrungspflicht variiert leicht je nach Steuerpflichtigenregime — bestätigen Sie Ihre spezifische Regel, statt anzunehmen, dass eine pauschale 5-Jahres-Frist einheitlich gilt.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Conservation', '[["Période de conservation","5 ans minimum, à partir du premier jour de l''année suivante"],["Ce qu''il faut conserver","XML, CDR, avis de rejet, résumés quotidiens"]]', 'L''obligation exacte de conservation varie légèrement selon le régime du contribuable — vérifiez votre règle spécifique plutôt que de présumer qu''un chiffre fixe de 5 ans s''applique uniformément.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 4 FROM countries WHERE name_en = 'Peru';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'CPE document family', '[["Sales","Invoices, boletas de venta"],["Adjustments","Credit and debit notes"],["Tax-related","Withholding and perception vouchers"],["Other","Public service receipts, electronic purchase settlements, GRE (dispatch/transport guides)"],["Examples","\"Factura Electrónica\", \"Boleta de Venta Electrónica\""]]', 'Choosing the right CPE type matters — the wrong one can cost a deduction or a tax credit, not just cause paperwork. So does the label: these are formal document names fixed in regulation, not descriptions you may paraphrase.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Familia de documentos CPE', '[["Ventas","Facturas, boletas de venta"],["Ajustes","Notas de crédito y débito"],["Relacionados con impuestos","Comprobantes de retención y percepción"],["Otros","Recibos de servicios públicos, liquidaciones de compra electrónicas, GRE (guías de remisión/transporte)"],["Ejemplos","\"Factura Electrónica\", \"Boleta de Venta Electrónica\""]]', 'Elegir el tipo correcto de CPE importa: el equivocado puede costar una deducción o un crédito fiscal, no solo papeleo. La etiqueta también: son nombres de documento formales fijados en la normativa, no descripciones parafraseables.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'CPE-Dokumentenfamilie', '[["Verkäufe","Rechnungen, boletas de venta"],["Anpassungen","Gutschriften und Lastschriften"],["Steuerbezogen","Einbehaltungs- und Wahrnehmungsbelege"],["Sonstige","Belege für öffentliche Dienstleistungen, elektronische Kaufabrechnungen, GRE (Versand-/Transportbegleitscheine)"],["Beispiele","\"Factura Electrónica\", \"Boleta de Venta Electrónica\""]]', 'Der richtige CPE-Typ zählt: der falsche kann einen Abzug oder eine Steuergutschrift kosten, nicht bloß Papierkram. Ebenso die Bezeichnung — es sind förmliche, in der Verordnung festgelegte Dokumentnamen, keine frei formulierbaren Beschreibungen.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Famille de documents CPE', '[["Ventes","Factures, boletas de venta"],["Ajustements","Notes de crédit et de débit"],["Liés à la fiscalité","Justificatifs de retenue et de perception"],["Autres","Reçus de services publics, règlements d''achat électroniques, GRE (guides d''expédition/transport)"],["Exemples","\"Factura Electrónica\", \"Boleta de Venta Electrónica\""]]', 'Le bon type de CPE compte : le mauvais peut coûter une déduction ou un crédit de TVA, pas seulement de la paperasse. Le libellé aussi — ce sont des noms de documents formels fixés par la réglementation, non des descriptions à paraphraser.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Peru') AND d.section = 'file_format' AND d.sort_order = 4;

-- ---- Saudi Arabia: 15 rows -> 3/4/4/4 plus one card kept whole ----
DELETE FROM deep_dive_card_translations WHERE card_id IN (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Saudi Arabia' AND d.section = 'file_format');
DELETE FROM deep_dive_cards WHERE section = 'file_format' AND country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Saudi Arabia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Format & standard', '[["Syntax","UBL 2.1 XML, with ZATCA-specific extensions"],["Standard invoice packaging","PDF/A-3 with embedded XML"],["Language","Arabic, machine-readable (bilingual common in practice)"]]', 'The PDF/A-3-with-embedded-XML packaging mirrors France''s Factur-X approach — a human-readable rendering alongside the machine-readable data in a single file.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Formato y estándar', '[["Sintaxis","XML UBL 2.1, con extensiones específicas de ZATCA"],["Empaquetado de factura estándar","PDF/A-3 con XML incrustado"],["Idioma","Árabe, legible por máquina (bilingüe habitual en la práctica)"]]', 'El empaquetado PDF/A-3 con XML incrustado refleja el enfoque Factur-X de Francia — una representación legible por humanos junto con los datos legibles por máquina en un único archivo.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Format und Standard', '[["Syntax","UBL-2.1-XML, mit ZATCA-spezifischen Erweiterungen"],["Standard-Rechnungsverpackung","PDF/A-3 mit eingebettetem XML"],["Sprache","Arabisch, maschinenlesbar (zweisprachig in der Praxis üblich)"]]', 'Die PDF/A-3-Verpackung mit eingebettetem XML spiegelt Frankreichs Factur-X-Ansatz wider — eine menschenlesbare Darstellung zusammen mit den maschinenlesbaren Daten in einer einzigen Datei.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Format et norme', '[["Syntaxe","XML UBL 2.1, avec extensions spécifiques à ZATCA"],["Emballage de facture standard","PDF/A-3 avec XML intégré"],["Langue","Arabe, lisible par machine (bilingue courant en pratique)"]]', 'L''emballage PDF/A-3 avec XML intégré reflète l''approche Factur-X de la France — une représentation lisible par l''humain accompagnée des données lisibles par machine dans un seul fichier.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Saudi Arabia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Identifiers & registration', '[["UUID","Unique per invoice"],["IRN","Invoice Reference Number"],["Invoice hash","Chained to the prior invoice''s hash"],["Invoice counter value","Sequential, tamper-evident numbering"]]', 'A "Hash Mismatch" rejection means the XML content was altered after the hash was calculated — this is one of the most common Phase 2 integration errors.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Identificadores y registro', '[["UUID","Único por factura"],["IRN","Número de Referencia de Factura"],["Hash de la factura","Encadenado al hash de la factura anterior"],["Valor de contador de factura","Numeración secuencial, a prueba de manipulaciones"]]', 'Un rechazo por "Hash Mismatch" significa que el contenido XML se alteró después de calcular el hash — este es uno de los errores más comunes en la integración de la Fase 2.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Kennungen und Registrierung', '[["UUID","Eindeutig pro Rechnung"],["IRN","Invoice Reference Number"],["Rechnungs-Hash","Verkettet mit dem Hash der vorherigen Rechnung"],["Rechnungszählerwert","Fortlaufende, manipulationssichere Nummerierung"]]', 'Eine Ablehnung wegen "Hash Mismatch" bedeutet, dass der XML-Inhalt nach der Hash-Berechnung verändert wurde — dies ist einer der häufigsten Integrationsfehler in Phase 2.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Identifiants et enregistrement', '[["UUID","Unique par facture"],["IRN","Numéro de référence de facture"],["Hash de la facture","Chaîné au hash de la facture précédente"],["Valeur du compteur de factures","Numérotation séquentielle, inviolable"]]', 'Un rejet « Hash Mismatch » signifie que le contenu XML a été modifié après le calcul du hash — c''est l''une des erreurs d''intégration de phase 2 les plus courantes.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Saudi Arabia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Mandatory content', '[["Standard vs simplified","A standard invoice carries the buyer''s name, address and, where applicable, VAT number. A simplified one needs the seller, the goods and the tax."],["Arabic is required","Invoices are issued in Arabic, and another language may be added as a translation. The XML tag names stay English; the data does not."],["QR on every type from 2023","Simplified invoices have needed one since 4 December 2021, all types since 1 January 2023 — and on standard invoices ZATCA adds it at clearance."],["Line-level tax code","Every line carries a VAT tax code, the VAT total is stated in riyals, and the supply date appears whenever it differs from the issue date."]]', 'Two things are widely stated wrongly: that the QR code is only for simplified invoices, and that the seller must generate it for standard ones. Neither has been true since 1 January 2023.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Contenido obligatorio', '[["Estándar frente a simplificada","La factura estándar lleva nombre, dirección y, cuando proceda, NIF-IVA del comprador. La simplificada solo exige el vendedor, los bienes y el impuesto."],["El árabe es obligatorio","Las facturas se emiten en árabe y puede añadirse otro idioma como traducción. Los nombres de las etiquetas XML siguen en inglés; los datos no."],["QR en todos los tipos desde 2023","Las simplificadas lo exigen desde el 4 de diciembre de 2021 y todos los tipos desde el 1 de enero de 2023; en las estándar lo añade ZATCA al despachar."],["Código de impuesto por línea","Cada línea lleva un código de IVA, el total del impuesto se expresa en riales y la fecha de entrega figura siempre que difiera de la de emisión."]]', 'Dos afirmaciones circulan erróneamente: que el código QR es solo para facturas simplificadas y que el vendedor debe generarlo en las estándar. Ninguna es cierta desde el 1 de enero de 2023.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Pflichtangaben', '[["Standard oder vereinfacht","Die Standardrechnung nennt Name, Anschrift und ggf. USt-Nummer des Käufers. Die vereinfachte braucht nur Verkäufer, Ware und Steuer."],["Arabisch ist Pflicht","Rechnungen werden auf Arabisch ausgestellt; eine weitere Sprache darf als Übersetzung hinzukommen. Die XML-Tagnamen bleiben englisch, die Daten nicht."],["QR auf allen Typen ab 2023","Vereinfachte Rechnungen seit dem 4. Dezember 2021, alle Typen seit dem 1. Januar 2023 — bei Standardrechnungen fügt ZATCA ihn beim Clearing hinzu."],["Steuercode je Position","Jede Position trägt einen Steuercode, die Steuersumme wird in Riyal angegeben, und das Lieferdatum erscheint, sobald es vom Ausstellungsdatum abweicht."]]', 'Zwei Aussagen kursieren falsch: dass der QR-Code nur für vereinfachte Rechnungen gilt und dass der Verkäufer ihn bei Standardrechnungen erzeugen muss. Seit dem 1. Januar 2023 trifft beides nicht zu.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Mentions obligatoires', '[["Standard ou simplifiée","La facture standard porte le nom, l''adresse et, le cas échéant, le numéro de TVA de l''acheteur. La simplifiée n''exige que le vendeur, les biens et la taxe."],["L''arabe est obligatoire","Les factures sont émises en arabe, une autre langue pouvant s''ajouter en traduction. Les noms de balises XML restent anglais ; les données non."],["QR sur tous les types dès 2023","Les factures simplifiées depuis le 4 décembre 2021, tous les types depuis le 1er janvier 2023 — sur les standard, ZATCA l''ajoute au dédouanement."],["Code de taxe par ligne","Chaque ligne porte un code de TVA, le total de taxe s''exprime en riyals, et la date de livraison figure dès qu''elle diffère de la date d''émission."]]', 'Deux affirmations circulent à tort : que le code QR ne concerne que les factures simplifiées, et que le vendeur doit le générer sur les standard. Aucune n''est vraie depuis le 1er janvier 2023.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 2;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Saudi Arabia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Archiving', '[["Six years","Invoices, books and records are kept for at least six years from the end of the tax period they relate to."],["Capital assets run longer","Eleven years for movable capital assets and fifteen for immovable property — the adjustment period plus five years."],["Kept in the Kingdom","Records are held in Saudi Arabia. A server abroad qualifies only if it can be reached from an access point inside the Kingdom."],["Archive the XML","Keep the XML, or the PDF/A-3 carrying it, so the hash and the cryptographic stamp survive and ZATCA can reach the archive."]]', 'Articles 53 and 66 could not be read on ZATCA''s own site — its regulations PDF truncates before them — so they rest on a reproduction of the official English text, with the retention figures corroborated by ZATCA''s Capital Assets Guideline.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Conservación', '[["Seis años","Las facturas, los libros y los registros se conservan al menos seis años desde el fin del periodo fiscal al que se refieren."],["Los bienes de capital, más","Once años para los bienes de capital muebles y quince para los inmuebles: el periodo de ajuste más cinco años."],["Conservados en el Reino","Los registros se guardan en Arabia Saudí. Un servidor en el extranjero solo vale si es accesible desde un punto de acceso dentro del Reino."],["Archive el XML","Conserve el XML, o el PDF/A-3 que lo contiene, para que sobrevivan el hash y el sello criptográfico y ZATCA pueda acceder al archivo."]]', 'Los artículos 53 y 66 no pudieron leerse en el sitio de ZATCA — su PDF de reglamentos se trunca antes de llegar a ellos — por lo que se apoyan en una reproducción del texto oficial en inglés, con las cifras de conservación corroboradas por la Guía de Bienes de Capital de ZATCA.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Aufbewahrung', '[["Sechs Jahre","Rechnungen, Bücher und Aufzeichnungen werden mindestens sechs Jahre ab dem Ende des betroffenen Steuerzeitraums aufbewahrt."],["Anlagegüter länger","Elf Jahre für bewegliche Anlagegüter und fünfzehn für Immobilien — der Berichtigungszeitraum plus fünf Jahre."],["Aufbewahrung im Königreich","Die Unterlagen liegen in Saudi-Arabien. Ein Server im Ausland genügt nur, wenn er von einem Zugangspunkt im Königreich erreichbar ist."],["Das XML archivieren","Bewahren Sie das XML oder das PDF/A-3 damit auf, damit Hash und kryptografischer Stempel erhalten bleiben und ZATCA das Archiv erreichen kann."]]', 'Die Artikel 53 und 66 waren auf der ZATCA-Website nicht lesbar — ihr Verordnungs-PDF bricht davor ab — daher stützen sie sich auf eine Wiedergabe des amtlichen englischen Textes, wobei die Aufbewahrungsfristen durch ZATCAs Leitfaden zu Anlagegütern bestätigt sind.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Conservation', '[["Six ans","Les factures, livres et registres sont conservés au moins six ans à compter de la fin de la période fiscale concernée."],["Les biens d''équipement, plus longtemps","Onze ans pour les biens d''équipement mobiliers et quinze pour les immeubles — la période de régularisation plus cinq ans."],["Conservés dans le Royaume","Les registres sont détenus en Arabie saoudite. Un serveur à l''étranger ne convient que s''il est joignable depuis un point d''accès dans le Royaume."],["Archiver le XML","Conservez le XML, ou le PDF/A-3 qui le porte, afin que l''empreinte et le sceau cryptographique subsistent et que ZATCA puisse atteindre l''archive."]]', 'Les articles 53 et 66 n''ont pas pu être lus sur le site de ZATCA — son PDF de règlements s''interrompt avant eux — ils reposent donc sur une reproduction du texte officiel anglais, les durées de conservation étant corroborées par le guide des biens d''équipement de ZATCA.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 3;
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 4 FROM countries WHERE name_en = 'Saudi Arabia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'en', 'Cryptographic controls', '[["Signature algorithm","ECDSA (Elliptic Curve Digital Signature Algorithm)"],["Credential","Cryptographic Stamp Identifier (CSID)"],["Government layer","ZATCA applies its own stamp using its private key after clearance"]]', 'The chain of trust runs supplier → ZATCA → recipient: your ECDSA signature proves the invoice came from you, and ZATCA''s own stamp on top of that is what actually makes it legally valid.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'es', 'Controles criptográficos', '[["Algoritmo de firma","ECDSA (Elliptic Curve Digital Signature Algorithm)"],["Credencial","Identificador de Sello Criptográfico (CSID)"],["Capa gubernamental","ZATCA aplica su propio sello con su clave privada tras la compensación"]]', 'La cadena de confianza va de proveedor → ZATCA → receptor: su firma ECDSA demuestra que la factura proviene de usted, y el sello propio de ZATCA sobre ella es lo que realmente la hace legalmente válida.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'de', 'Kryptografische Kontrollen', '[["Signaturalgorithmus","ECDSA (Elliptic Curve Digital Signature Algorithm)"],["Berechtigungsnachweis","Cryptographic Stamp Identifier (CSID)"],["Behördenebene","ZATCA bringt nach der Freigabe mit ihrem privaten Schlüssel ihren eigenen Stempel an"]]', 'Die Vertrauenskette verläuft Lieferant → ZATCA → Empfänger: Ihre ECDSA-Signatur belegt, dass die Rechnung von Ihnen stammt, und ZATCAs eigener Stempel darauf macht sie tatsächlich rechtsgültig.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body)
SELECT d.id, 'fr', 'Contrôles cryptographiques', '[["Algorithme de signature","ECDSA (Elliptic Curve Digital Signature Algorithm)"],["Justificatif","Identifiant de cachet cryptographique (CSID)"],["Couche gouvernementale","ZATCA appose son propre cachet avec sa clé privée après le contrôle"]]', 'La chaîne de confiance va du fournisseur → ZATCA → destinataire : votre signature ECDSA prouve que la facture provient de vous, et le cachet propre de ZATCA apposé par-dessus est ce qui la rend réellement valide juridiquement.', NULL FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Saudi Arabia') AND d.section = 'file_format' AND d.sort_order = 4;

